        lines.append('- ' + name + ' (product_id ' + ref + '): ' + money(full) + ' past due, ' + str(days) + ' days late. Lowest amount: ' + money(fl) + '. Latest promise date: ' + spoken_date(deadline) + ' (' + deadline.isoformat() + ').')
    ask = 'Can you make this payment today?' if len(facts) == 1 else 'Can you pay all of them today?'
