159	    {"target_node": "next_offer", "description": "No to today: start the proposals", "condition": {"logic": "or", "conditions": [{"variable": "first_answer", "operator": "equals", "operand": "refused"}, {"variable": "first_answer", "operator": "equals", "operand": "too_much"}]}},
160	    {"target_node": "mark_all", "description": "Paid, dispute or does not want to talk", "condition": {"logic": "or", "conditions": [{"variable": "first_answer", "operator": "equals", "operand": "paid"}, {"variable": "first_answer", "operator": "equals", "operand": "dispute"}, {"variable": "first_answer", "operator": "equals", "operand": "end_talk"}]}}
161	   ]
162	  },
163	  "today_prep": {
164	   "name": "today_prep", "node_type": "code", "passthrough": true, "passthrough_default_transition": "next_offer",
165	   "on_enter": {"type": "silent"}, "disable_inactivity_monitor": true,
166	   "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {"code": {"type": "string", "default": "import datetime
import json

def is_business_day(d, holidays):
    return d.weekday() < 5 and d not in holidays

def next_business_day(d, holidays, include_today=False):
    if include_today and is_business_day(d, holidays):
        return d
    d = d + datetime.timedelta(days=1)
    while not is_business_day(d, holidays):
        d = d + datetime.timedelta(days=1)
    return d

try:
    today = datetime.date.fromisoformat(str(vars.get('now'))[:10])
    hol = set(datetime.date.fromisoformat(x) for x in ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
    d = next_business_day(today, hol, True)
    facts = json.loads(vars.get('facts_json') or '[]')
    vars['agreements_json'] = json.dumps([dict(ref=g['ref'], name=g['name'], amount=g['full'], date=d.isoformat(), adjusted=False) for g in facts])
    vars['offer_item'] = str(len(facts))
except Exception:
