        late = days >= 8
        deadline = add_business_days(today, 7 if late else 12, hol)
        week_end = last_business_day_of_week(today, hol)
        if week_end is None or week_end <= today:
            week_end = last_business_day_of_week(today + datetime.timedelta(days=7), hol)
        a1 = min(week_end, deadline) if week_end else deadline
        ref = str(it.get('product_id') or '')
        facts.append(dict(ref=ref, name=name, full=full, floor=fl, deadline=deadline.isoformat(), a1=a1.isoformat()))
        steps = [dict(text='Could you pay ' + money(full) + ' for your ' + name + ' by ' + spoken_date(a1) + '?', amount=full, date=a1.isoformat(),
                      floor_text='Could you pay ' + money(fl) + ' for your ' + name + ' by ' + spoken_date(a1) + '? The rest stays overdue.')]
        if late:
