        offers.append(dict(ref=ref, name=name, floor=fl, steps=steps))
        said.append('Your ' + name + ' has ' + money(full) + ' past due and is ' + str(days) + ' days late.')
        lines.append('- ' + name + ' (product_id ' + ref + '): ' + money(full) + ' past due, ' + str(days) + ' days late. Lowest amount: ' + money(fl) + '. Latest promise date: ' + spoken_date(deadline) + ' (' + deadline.isoformat() + ').')
    ask = 'Can you make this payment today?' if len(facts) == 1 else 'Can you pay all of them today?'
    vars['statement_text'] = 'I am calling from the collections team about a late payment. ' + ' '.join(said) + ' ' + ask
    vars['facts_text'] = 'Today is ' + spoken_date(today) + ' (' + today.isoformat() + ').\n' + '\n'.join(lines)
    vars['facts_json'] = json.dumps(facts)
    vars['offers_json'] = json.dumps(offers)
    vars['product_count'] = str(len(facts))
    vars['facts_state'] = 'ok' if facts else 'empty'
